INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Customizing dasselbe wie Programmieren?', 2, '[{"text": "Nein", "correct": true, "because": "Customizing passt bestehende Software an"}, {"text": "Ja", "correct": false, "because": "Programmieren erstellt neu"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Customizing?', 3, '[{"text": "Software an Bedürfnisse anpassen", "correct": true, "because": "Optimierung für Nutzer"}, {"text": "Hardware verbessern", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Kosten senken", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche umfasst Customizing oft?', 5, '[{"text": "Benutzeroberfläche", "correct": true, "because": "Anpassung an Nutzer"}, {"text": "Workflows", "correct": true, "because": "Prozesse optimieren"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Customizing nutzt vorhandene Tools. b) Es erfordert immer neue Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine neue Software nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Customizing?', 4, '[{"text": "Anforderungen", "correct": false, "because": "Grundlage der Anpassung"}, {"text": "Dokumentation", "correct": false, "because": "Wichtig für Nachvollziehbarkeit"}, {"text": "Bildschirmfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Customizing immer teuer ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten variieren nach Umfang"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches System wird oft angepasst?', 3, '[{"text": "SAP", "correct": true, "because": "Häufiges Customizing-Ziel"}, {"text": "Windows", "correct": false, "because": "Weniger typisch"}, {"text": "Linux", "correct": false, "because": "Eher Open Source"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Customizing?', 5, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Prozesse optimiert"}, {"text": "Nutzerakzeptanz", "correct": true, "because": "Anpassung an Bedürfnisse"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Hardware-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Customizing ist flexibel. b) Es macht Updates unmöglich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Updates bleiben möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Customizing?', 4, '[{"text": "Systemkenntnisse", "correct": false, "because": "Verständnis nötig"}, {"text": "Anforderungsanalyse", "correct": false, "because": "Basis der Anpassung"}, {"text": "3D-Drucker", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Customizing nur für große Firmen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMUs nutzen es"}, {"text": "Ja", "correct": false, "because": "Skalierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zum Customizing?', 4, '[{"text": "Anforderungsdefinition", "correct": true, "because": "Startpunkt"}, {"text": "Konfiguration", "correct": true, "because": "Umsetzung"}, {"text": "Hardware-Upgrade", "correct": false, "because": "Nicht nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Customizing keine Programmierung braucht. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Oft nur Konfiguration"}, {"text": "Nein", "correct": false, "because": "Manchmal nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Customizing?', 3, '[{"text": "Nutzerbedürfnisse", "correct": true, "because": "Ziel der Anpassung"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Minimale Kosten", "correct": false, "because": "Effizienz wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Customizing optimiert Prozesse. b) Es ist einmalig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kontinuierlich anpassbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools helfen beim Customizing?', 5, '[{"text": "Konfigurationstools", "correct": true, "because": "Systemanpassung"}, {"text": "Dokumentationssoftware", "correct": true, "because": "Änderungen nachvollziehbar"}, {"text": "Spieleplattform", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Anpassung unwichtig?', 3, '[{"text": "Systemkompatibilität", "correct": false, "because": "Muss passen"}, {"text": "Testphase", "correct": false, "because": "Sichert Funktion"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Verändert Customizing den Quellcode?', 3, '[{"text": "Nein", "correct": true, "because": "Meist Konfiguration"}, {"text": "Ja", "correct": false, "because": "Nur bei Entwicklung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Customizing für alle Software geht?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Flexibilität"}, {"text": "Ja", "correct": false, "because": "Nicht immer möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Dokumentation?', 4, '[{"text": "Nachvollziehbarkeit", "correct": true, "because": "Änderungen verfolgbar"}, {"text": "Kostensteigerung", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Schnellere Updates", "correct": false, "because": "Indirekt"}]');
